import assert from 'node:assert/strict';
import test from 'node:test';
import { legacyBrain } from './brains/legacy';
import { buildAIPlan } from './index';
import { GameState, Snake } from '../../types/game';

// ─── Golden-master fixtures for the legacy brain ───────────────────────────
// Every expectation below was generated by running the ORIGINAL code: the
// ai.ts of commit 611c236, driven by that commit's App.tsx planning loop, on
// exactly these boards. The lifted brain in brains/legacy.ts must reproduce
// them move-for-move, including the old dynamic lock counts. If a fixture
// fails, the lift drifted — the fixture is right by definition.

function makeSnake(overrides: Partial<Snake>): Snake {
  return {
    id: 'p2',
    name: 'LEGACY',
    body: [{ x: 5, y: 5 }, { x: 6, y: 5 }, { x: 7, y: 5 }],
    direction: 'LEFT',
    queuedDirection: null,
    score: 0,
    skillPoints: 0,
    isAlive: true,
    color: '#000',
    equippedSkill: 'dart',
    pendingSkill: null,
    ...overrides,
  } as Snake;
}

function makeState(p1: Partial<Snake>, p2: Partial<Snake>, extra: Partial<GameState> = {}): GameState {
  return {
    phase: 'TOKEN_RACE',
    tick: 0,
    turn: 0,
    snakes: [
      makeSnake({ id: 'p1', name: 'PLAYER 1', ...p1 }),
      makeSnake({ ...p2 }),
    ],
    tokens: [{ x: 7, y: 7 }],
    ringInset: 0,
    skillsAvailable: 'immediate',
    ...extra,
  } as GameState;
}

const mv = (direction: string) => ({ type: 'move', direction });

function assertGoldenMaster(
  name: string,
  state: GameState,
  difficulty: 'EASY' | 'MEDIUM' | 'HARD',
  expectedPlan: { type: string; direction: string }[],
  expectedLockCount: number,
) {
  test(`legacy golden-master: ${name}`, () => {
    const result = legacyBrain.plan({
      gameState: state,
      gridSize: 8,
      botRole: 'p2',
      difficulty,
      raceTurns: 20,
    });
    assert.deepEqual(result.plan, expectedPlan);
    assert.equal(result.lockCount, expectedLockCount);
  });
}

assertGoldenMaster(
  'open-board-medium',
  makeState(
    { body: [{ x: 1, y: 1 }, { x: 1, y: 2 }, { x: 1, y: 3 }], direction: 'UP' },
    { body: [{ x: 4, y: 4 }, { x: 4, y: 5 }, { x: 4, y: 6 }], direction: 'UP' },
    { tokens: [{ x: 4, y: 1 }] },
  ),
  'MEDIUM',
  [mv('UP'), mv('UP'), mv('UP')],
  3,
);

assertGoldenMaster(
  'token-race-hard',
  makeState(
    { body: [{ x: 2, y: 5 }, { x: 2, y: 6 }, { x: 2, y: 7 }], direction: 'UP', skillPoints: 7, score: 6 },
    { body: [{ x: 5, y: 5 }, { x: 5, y: 6 }, { x: 5, y: 7 }], direction: 'UP', skillPoints: 8, score: 7 },
    { tokens: [{ x: 4, y: 2 }] },
  ),
  'HARD',
  [mv('UP'), mv('UP'), mv('UP')],
  3,
);

assertGoldenMaster(
  'corner-exit-locks-one-hard',
  makeState(
    { body: [{ x: 7, y: 7 }, { x: 7, y: 6 }, { x: 7, y: 5 }], direction: 'UP' },
    { body: [{ x: 1, y: 0 }, { x: 2, y: 0 }, { x: 3, y: 0 }, { x: 4, y: 0 }], direction: 'LEFT' },
    { tokens: [{ x: 0, y: 0 }] },
  ),
  'HARD',
  [mv('LEFT'), mv('DOWN'), mv('DOWN')],
  1, // destination after move 0 has a single safe escape → old lock rule locks 1
);

assertGoldenMaster(
  'forced-move-easy',
  makeState(
    { body: [{ x: 7, y: 7 }, { x: 6, y: 7 }, { x: 5, y: 7 }], direction: 'UP' },
    { body: [{ x: 3, y: 0 }, { x: 4, y: 0 }, { x: 5, y: 0 }, { x: 6, y: 0 }], direction: 'LEFT' },
    { tokens: [{ x: 0, y: 0 }], walls: [{ x: 3, y: 1 }, { x: 2, y: 1 }, { x: 1, y: 1 }] },
  ),
  'EASY',
  [mv('LEFT'), mv('LEFT'), mv('LEFT')],
  3,
);

assertGoldenMaster(
  'dead-end-pocket-veto-hard',
  makeState(
    { body: [{ x: 0, y: 7 }, { x: 0, y: 6 }, { x: 0, y: 5 }], direction: 'DOWN' },
    { body: [{ x: 4, y: 2 }, { x: 4, y: 1 }, { x: 4, y: 0 }], direction: 'DOWN' },
    { tokens: [{ x: 4, y: 4 }, { x: 7, y: 7 }], walls: [{ x: 3, y: 4 }, { x: 5, y: 4 }, { x: 4, y: 5 }] },
  ),
  'HARD',
  // Approaches the pocket mouth, then refuses the bait token at (4,4):
  // entering it floods to 1 cell < body length 3, so the old veto fires.
  [mv('DOWN'), mv('RIGHT'), mv('RIGHT')],
  3,
);

assertGoldenMaster(
  'head-on-veto-hard',
  makeState(
    { body: [{ x: 3, y: 3 }, { x: 2, y: 3 }, { x: 1, y: 3 }], direction: 'RIGHT', skillPoints: 8, score: 6 },
    { body: [{ x: 5, y: 3 }, { x: 6, y: 3 }, { x: 7, y: 3 }], direction: 'LEFT', skillPoints: 7, score: 7 },
    { tokens: [{ x: 4, y: 3 }] },
  ),
  'HARD',
  // The token cell (4,3) is in the opponent's reach and the bot loses that
  // tiebreak (SP 7 vs 8) → the old HARD rule vetoes the contest outright.
  [mv('UP'), mv('UP'), mv('LEFT')],
  3,
);

test('legacy golden-master: dispatch through the public API (LEGACY_HARD)', () => {
  const state = makeState(
    { body: [{ x: 2, y: 5 }, { x: 2, y: 6 }, { x: 2, y: 7 }], direction: 'UP', skillPoints: 7, score: 6 },
    { body: [{ x: 5, y: 5 }, { x: 5, y: 6 }, { x: 5, y: 7 }], direction: 'UP', skillPoints: 8, score: 7 },
    { tokens: [{ x: 4, y: 2 }] },
  );
  const result = buildAIPlan({
    gameState: state,
    gridSize: 8,
    botRole: 'p2',
    difficulty: 'HARD',
    aiStyle: 'LEGACY_HARD',
    raceTurns: 20,
  });
  assert.deepEqual(result.plan, [mv('UP'), mv('UP'), mv('UP')]);
  assert.equal(result.lockCount, 3);
});

test('legacy golden-master: single-move action matches the lifted rating', () => {
  const state = makeState(
    { body: [{ x: 3, y: 3 }, { x: 2, y: 3 }, { x: 1, y: 3 }], direction: 'RIGHT', skillPoints: 8, score: 6 },
    { body: [{ x: 5, y: 3 }, { x: 6, y: 3 }, { x: 7, y: 3 }], direction: 'LEFT', skillPoints: 7, score: 7 },
    { tokens: [{ x: 4, y: 3 }] },
  );
  const action = legacyBrain.action!({
    gameState: state,
    gridSize: 8,
    botRole: 'p2',
    difficulty: 'HARD',
  });
  assert.equal(action.direction, 'UP'); // same veto as the plan's first ply
  assert.equal(action.skill, null);
});
